{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "All-trans retinoic acid, the closest retinoid scaffold to the query, is reported to exhibit low and erratic oral bioavailability in its available oral formulation, demonstrating that the retinoid backbone can have poor systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "13-cis retinoic acid has low absolute bioavailability due to variable gastrointestinal absorption and gut degradation; this direct measurement in the same retinoid acid family supports a low F outcome for the query's more lipophilic amide derivative.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "A human absolute bioavailability of 52% for tretinoin indicates that the retinoid scaffold can be well absorbed under some conditions, which would argue for high bioavailability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C38"],
      "claim": "Acitretin, a related retinoid, has an absolute bioavailability of 60% (range 36-95%), supporting the possibility of high oral bioavailability for retinoid-like molecules.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is fenretinide, the p-hydroxyphenylamide of all-trans retinoic acid. The closest retinoid acid analogues show conflicting results, but the low/erratic absolute bioavailability records are more transferable to this amide because the added p-hydroxyanilide increases molecular weight and lipophilicity, lowers aqueous solubility, and introduces a phenol subject to first-pass glucuronidation. The moderate-to-high F values for tretinoin, acitretin, and etretinate are mostly for carboxylic acids/esters and do not account for these amide-specific liabilities; the balance of evidence favors F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide is included; human absolute F is not established because an IV formulation is lacking.",
    "The provided retinoid records are for acids/esters, not amides; the effect of the amide bond and phenolic group on absorption and first-pass metabolism must be inferred.",
    "Conflicting reports for all-trans retinoic acid (low/erratic vs ~50%) create uncertainty in extrapolation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

